    const void* input,
    void* packed_output,
    void* scale_output,
    int64_t rows,
    int64_t cols,
    int dtype,
    void* stream) {
    if (input == nullptr || packed_output == nullptr || scale_output == nullptr ||
        stream == nullptr || rows <= 0 || cols <= 0 || (cols % 32) != 0 ||
        dtype < 0 || dtype > 1) {
        return static_cast<int>(hipErrorInvalidValue);
