180	        abs_values[tid] = fmaxf(abs_values[tid], abs_values[tid + 16]);
181	    }
182	    __syncthreads();
183	    if (tid < 8) {
184	        abs_values[tid] = fmaxf(abs_values[tid], abs_values[tid + 8]);
185	    }
186	    __syncthreads();
187	    if (tid < 4) {
188	        abs_values[tid] = fmaxf(abs_values[tid], abs_values[tid + 4]);
189	    }
190	    __syncthreads();
191	    if (tid < 2) {
192	        abs_values[tid] = fmaxf(abs_values[tid], abs_values[tid + 2]);
193	    }
194	    __syncthreads();
195	    if (tid == 0) {
196	        abs_values[0] = fmaxf(abs_values[0], abs_values[1]);
197	        const int exponent = compute_exponent(abs_values[0]);
198	        scale_output[row * static_cast<int64_t>(groups) + group] =
199	            static_cast<uint8_t>(exponent + 127);
200	        abs_values[0] = pow2_int(-exponent);
201	    }
202	    __syncthreads();
203	
204	    if (tid < 16) {
205	        const float inv_scale = abs_values[0];
206	        const int col0 = col_base + tid * 2;
207	        const int col1 = col0 + 1;
208	        const int64_t idx0 = row_offset + col0;
209	        const int64_t idx1 = row_offset + col1;
210	        const float mag0 = fabsf(load_value<IsBf16>(input, idx0)) * inv_scale;
211	        const float mag1 = fabsf(load_value<IsBf16>(input, idx1)) * inv_scale;
212	        const uint8_t q0 = quantize_mxfp4_even(mag0, load_sign_bit(input, idx0));
213	        const uint8_t q1 = quantize_mxfp4_even(mag1, load_sign_bit(input, idx1));
214	
215	        packed_output[row * (cols / 2) + group * 16 + tid] =
216	            static_cast<uint8_t>(q0 | static_cast<uint8_t>(q1 << 4));
217	    }
218	}
